MAKE_ROW_NEW = 'function makeRow(s,col,v,colV,tSug,stk){\n  var vp=colV>0?Math.round(v/colV*100):0;\n  var net=Math.max(0,tSug-stk);\n  var over=stk>0&&tSug>0&&stk>=tSug;\n  var prodCol=net>0?\'#86efac\':(over?\'#7a7b95\':\'#10b981\');\n  var stkBadge=\'\';\n  if(stk>0){\n    var bg=over?\'rgba(239,68,68,.15)\':\'rgba(255,193,7,.15)\';\n    var bd=over?\'#ef444466\':\'#ffc10744\';\n    var fc=over?\'#ef4444\':\'#ffc107\';\n    stkBadge=\'<div style="background:\'+bg+\';border:1px solid \'+bd+\';border-radius:4px;padding:0 4px;color:\'+fc+\';font-size:0.58rem;font-weight:700;min-width:24px;text-align:center" title="\'+(over?\'Sobrestock vs demanda\':\'Stock PT\')+\'">\'+stk+\'</div>\';\n  }else stkBadge=\'<div style="min-width:24px"></div>\';\n  return \'<div style="display:flex;align-items:center;gap:5px;padding:2px 0;border-bottom:1px solid var(--brd);font-size:0.69rem">\'+\n    \'<div style="width:24px;text-align:center;font-weight:700;color:#c0c0e8">\'+s+\'</div>\'+\n    \'<div style="flex:1;background:#16171f;border-radius:3px;height:4px;overflow:hidden"><div style="height:4px;border-radius:3px;background:\'+cn(col)+\'88;width:\'+vp+\'%"></div></div>\'+\n    \'<div style="color:#a5b4fc;font-weight:700;width:26px;text-align:right">\'+vp+\'%</div>\'+\n    \'<div style="color:var(--mu);width:22px;text-align:right;font-size:0.61rem">\'+v+\'u</div>\'+\n    \'<div style="color:\'+prodCol+\';font-size:0.61rem;font-weight:700;width:38px;text-align:right" title="Demanda \'+tSug+\'u">\'+(net>0?(\'+\'+net):\'0\')+\'</div>\'+\n    stkBadge+\'</div>\';\n}'
